html:
{%- set src = frappe.get_doc(doc.source_doctype, doc.source_name) if doc.source_name else None -%}
{%- set live = doc.companies | selectattr("sales_invoice") | list -%}
<style>
	.ccm { font-size: 11.5px; color: #111; }
	.ccm h2 { font-size: 18px; margin: 0; }
	.ccm .muted { color: #666; }
	.ccm table { width: 100%; border-collapse: collapse; }
	.ccm th, .ccm td { padding: 4px 6px; border-bottom: 1px solid #ddd; text-align: left; vertical-align: top; }
	.ccm .r { text-align: right; }
	.ccm .seller { border: 1px solid #bbb; border-left: 5px solid #d81b60; border-radius: 4px; padding: 8px 10px; margin-top: 12px; page-break-inside: avoid; }
	.ccm .seller-h { display: flex; justify-content: space-between; margin-bottom: 4px; }
	.ccm .total { font-size: 15px; font-weight: 700; }
	.ccm .note { border: 1px dashed #999; padding: 6px 8px; margin-top: 12px; font-size: 10.5px; }
</style>
<div class="ccm">
	<table style="border:0">
		<tr>
			<td style="border:0">
				<h2>{{ _("Customer Cash Memo") }}</h2>
				<div class="muted">{{ _("Ref") }} {{ doc.name }} · {{ frappe.utils.format_date(doc.posting_date) }}{% if src %} · {{ src.name }}{% endif %}</div>
			</td>
			<td style="border:0" class="r">
				<b>{{ doc.customer_name }}</b><br>
				{% if src and src.get("mobile_no") %}{{ src.mobile_no }}<br>{% endif %}
				{% if doc.vehicle %}{{ _("Vehicle") }}: <b>{{ doc.vehicle }}</b>{% endif %}
			</td>
		</tr>
	</table>

	{% for row in live %}
	{%- set si = frappe.get_doc("Sales Invoice", row.sales_invoice) -%}
	{%- set comp = frappe.db.get_value("Company", si.company, ["company_name", "tax_id", "phone_no"], as_dict=True) -%}
	<div class="seller">
		<div class="seller-h">
			<div><b>{{ comp.company_name }}</b>{% if comp.tax_id %} · {{ _("GSTIN") }} {{ comp.tax_id }}{% endif %}</div>
			<div>{{ _("Tax Invoice") }} <b>{{ si.name }}</b>{% if si.docstatus == 2 %} ({{ _("Cancelled") }}){% endif %}</div>
		</div>
		<table>
			<thead><tr><th>{{ _("Item / Service") }}</th><th class="r">{{ _("Qty") }}</th><th class="r">{{ _("Rate") }}</th><th class="r">{{ _("Amount") }}</th></tr></thead>
			<tbody>
			{% for it in si.items %}
				<tr>
					<td>{{ it.item_name }}{% if it.discount_percentage %} <span class="muted">(-{{ frappe.utils.flt(it.discount_percentage, 2) }}%)</span>{% endif %}</td>
					<td class="r">{{ "%g"|format(it.qty) }} {{ it.uom }}</td>
					<td class="r">{{ frappe.utils.fmt_money(it.rate, currency=si.currency) }}</td>
					<td class="r">{{ frappe.utils.fmt_money(it.amount, currency=si.currency) }}</td>
				</tr>
			{% endfor %}
			{% if si.discount_amount %}
				<tr><td colspan="3" class="r">{{ _("Bill discount") }}</td><td class="r">- {{ frappe.utils.fmt_money(si.discount_amount, currency=si.currency) }}</td></tr>
			{% endif %}
			{% for t in si.taxes %}
				<tr><td colspan="3" class="r muted">{{ t.description }}</td><td class="r">{{ frappe.utils.fmt_money(t.tax_amount, currency=si.currency) }}</td></tr>
			{% endfor %}
			{% if si.rounding_adjustment %}
				<tr><td colspan="3" class="r muted">{{ _("Rounding") }}</td><td class="r">{{ frappe.utils.fmt_money(si.rounding_adjustment, currency=si.currency) }}</td></tr>
			{% endif %}
				<tr><td colspan="3" class="r"><b>{{ _("Invoice total") }}</b></td><td class="r"><b>{{ frappe.utils.fmt_money(si.rounded_total or si.grand_total, currency=si.currency) }}</b></td></tr>
			</tbody>
		</table>
	</div>
	{% endfor %}

	<table style="margin-top:12px">
		<tr><td class="total">{{ _("Total for this visit") }}</td><td class="r total">{{ frappe.utils.fmt_money(doc.total_amount, currency=frappe.db.get_default("currency")) }}</td></tr>
		{% for p in doc.payments %}
		<tr><td>{{ _("Paid by") }} {{ p.mode_of_payment }}{% if p.reference_no %} ({{ p.reference_no }}){% endif %}</td><td class="r">{{ frappe.utils.fmt_money(p.amount) }}</td></tr>
		{% endfor %}
		{% if doc.change_due %}<tr><td>{{ _("Change returned") }}</td><td class="r">{{ frappe.utils.fmt_money(doc.change_due) }}</td></tr>{% endif %}
		{% if doc.outstanding_amount and doc.outstanding_amount > 0.5 %}<tr><td><b>{{ _("Balance due") }}</b></td><td class="r"><b>{{ frappe.utils.fmt_money(doc.outstanding_amount) }}</b></td></tr>{% endif %}
	</table>

	<div class="note">
		{{ _("This memo summarises separate tax invoices issued by each company named above for your visit. Each company is the legal seller of the items on its invoice; please refer to the individual tax invoice for GST purposes.") }}
	</div>
</div>
